// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract Log {
    event LogEvent(address indexed _contract, address indexed _caller, string _logName, bytes _data);

    // minimal state to demonstrate the effect of an external call
    address public lastContract;
    address public lastCaller;
    string public lastLogName;
    bytes public lastData;

    // Originally this was named `Log` (which older compilers treated as a constructor).
    // Here we keep the same signature but give it a different name so the function is callable
    // by anyone and emits an event — demonstrating missing access control.
    function logEvent(
        address _contract,
        address _caller,
        string memory _logName,
        bytes memory _data
    ) public {
        lastContract = _contract;
        lastCaller = _caller;
        lastLogName = _logName;
        lastData = _data;
        emit LogEvent(_contract, _caller, _logName, _data);
    }
}

contract LogTest is Test {
    Log target;
    address attacker;

    function setUp() public {
        target = new Log();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_logEvent() public {
        // Attacker calls the public function and injects a spoofed log
        vm.prank(attacker);
        target.logEvent(address(0xDEAD), attacker, "AdminAction", hex"1122");

        // Verify the call succeeded and state reflects the attacker's input
        assertEq(target.lastCaller(), attacker);
        assertEq(target.lastContract(), address(0xDEAD));
        assertEq(target.lastLogName(), "AdminAction");
    }
}

