contract DnGmxBatchingManager {
    struct UserDeposit { uint128 usdcBalance; uint128 unclaimedShares; uint256 round; }
    struct RoundDeposit { uint128 totalUsdc; uint128 totalShares; }
    struct VaultBatchingState { uint256 currentRound; uint256 roundGlpStaked; uint256 roundUsdcBalance; mapping(address => UserDeposit) userDeposits; mapping(uint256 => RoundDeposit) roundDeposits; }

    address public dnGmxJuniorVault;
    uint256 public dnGmxJuniorVaultGlpBalance;
    MockERC20 public sGlp;
    MockERC20 public usdc;
    VaultBatchingState public vaultBatchingState;
    bool private _paused;

    constructor(address _sGlp, address _usdc, address _vault) {
        sGlp = MockERC20(_sGlp);
        usdc = MockERC20(_usdc);
        dnGmxJuniorVault = _vault;
        vaultBatchingState.currentRound = 1;
        _paused = true; // start paused to show executeBatchDeposit can unpause
    }

    modifier whenNotPaused() { require(!_paused, "paused"); _; }
    function paused() public view returns (bool) { return _paused; }
    function _unpause() internal { _paused = false; }
    function _pause() internal { _paused = true; }

    // Minimal depositUsdc to show it's guarded by whenNotPaused
    function depositUsdc(uint256 amount, address receiver) external whenNotPaused returns (uint256) {
        require(amount>0 && receiver!=address(0));
