        if (paused()) _unpause();
        if (dnGmxJuniorVaultGlpBalance > 0) {
            uint256 glpToTransfer = dnGmxJuniorVaultGlpBalance;
            dnGmxJuniorVaultGlpBalance = 0;
            sGlp.transfer(dnGmxJuniorVault, glpToTransfer);
        }
        _executeVaultUserBatchDeposit();
    }

    function _executeVaultUserBatchDeposit() internal {
        if (vaultBatchingState.roundGlpStaked == 0) return;
        uint256 totalShares = MockVault(dnGmxJuniorVault).deposit(vaultBatchingState.roundGlpStaked, address(this));
        vaultBatchingState.roundDeposits[vaultBatchingState.currentRound] = RoundDeposit(uint128(vaultBatchingState.roundUsdcBalance), uint128(totalShares));
        vaultBatchingState.roundUsdcBalance = 0;
        vaultBatchingState.roundGlpStaked = 0;
        vaultBatchingState.currentRound++;
    }

    // helpers for test to set internal state
    function mockSetDnGmxJuniorVaultGlpBalance(uint256 v) external { dnGmxJuniorVaultGlpBalance = v; }
