contract MainVault {
    address public xProvider;
    address public vaultCurrency;
    enum State { Idle, SendingFundsXChain }
    State public state;
    uint256 public amountToSendXChain;

    constructor(address _token) { vaultCurrency = _token; }

    function setHomeXProvider(address _x) public { xProvider = _x; }
    function setAmountToSend(uint256 a) public { amountToSendXChain = a; }
    function setState(uint8 s) public { state = State(s); }
