    function _assessState(ProtectionPoolState storage poolState) internal {
        poolState.updatedTimestamp = block.timestamp;
        (address[] memory pools, LendingPoolStatus[] memory statuses) = poolState.protectionPool.assessLendingPools();
        for (uint256 j = 0; j < pools.length; ++j) {
            address lp = pools[j];
            LendingPoolStatus prev = poolState.lendingPoolStateDetails[lp].currentStatus;
            LendingPoolStatus cur = statuses[j];
