// Minimal pair contract used by Seal.breed
contract Pair {
    Token public seal;
    Token public token;
    uint256 public reserveSeal;
    uint256 public reserveToken;
    mapping(address => uint256) public lpBalance;
    constructor(Token _seal, Token _token) { seal = _seal; token = _token; }
    function sync() external {
        reserveSeal = seal.balanceOf(address(this));
        reserveToken = token.balanceOf(address(this));
    }
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata) external {
        if (amount1Out > 0) {
            // send token to `to`
            token.transfer(to, amount1Out);
            reserveToken -= amount1Out;
        }
        if (amount0Out > 0) {
            seal.transfer(to, amount0Out);
            reserveSeal -= amount0Out;
        }
    }
    function mint(address to) external {
        lpBalance[to] += 1;
    }
}

contract Seal {
    Token public seal;
    Token public token;
    Pair public cSeal;
    uint256 public today;
    uint256 public spawnRate; // scaled by 1e18

    constructor() {
        seal = new Token("SEAL");
        token = new Token("TOKEN");
        cSeal = new Pair(seal, token);
        // seed initial liquidity in pair
        seal.mint(address(cSeal), 1000 ether);
        token.mint(address(cSeal), 1000 ether);
        cSeal.sync();
        spawnRate = 1e18; // 1:1
        today = 0;
    }

    // vulnerable function: only guarded by time check
    function breed() external {
        require(block.timestamp / 1 days > today, "too soon");
        today += 1;
        uint256 sealPairAmount = cSeal.reserveSeal();
        uint256 tokenPairAmount = token.balanceOf(address(cSeal));
        uint256 newSeal = sealPairAmount * spawnRate / 1e18;
        uint256 amount = getAmountOut(newSeal, sealPairAmount, tokenPairAmount);
        seal.mint(address(cSeal), newSeal);
        if (address(seal) < address(token))
            cSeal.swap(0, amount, address(this), "");
        else
            cSeal.swap(amount, 0, address(this), "");
        // send tokens back to pair
        token.transfer(address(cSeal), amount);
        // additional minting without access control
        seal.mint(address(cSeal), newSeal);
        cSeal.mint(address(this));
    }

    // simplified Uniswap getAmountOut (no fees)
    function getAmountOut(uint amountIn, uint reserveIn, uint reserveOut) internal pure returns (uint) {
        if (reserveIn + amountIn == 0) return 0;
        return (amountIn * reserveOut) / (reserveIn + amountIn);
    }
}

