    address attacker;

    function setUp() public {
        target = new Seal();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_breed() public {
        // advance time so the day-check passes
        vm.warp(block.timestamp + 1 days);
        vm.prank(attacker);
        uint256 before = target.seal().totalSupply();
        target.breed();
        uint256 after = target.seal().totalSupply();
        // attacker (anyone) was able to trigger minting -> totalSupply increased
        assertTrue(after > before);
    }
}

