    function mint(address to, uint256 a) external { bal[to] += a; }
    function safeTransferFrom(address from, address to, uint256 amount) external { if (amount > 0) { require(bal[from] >= amount); bal[from] -= amount; bal[to] += amount; } }
}

contract TreasureNFTOracle { function reportSale(address, uint256, address, uint256) external {} }

contract TreasureDAO {
    struct Listing { uint256 quantity; uint256 pricePerItem; }
    mapping(address => mapping(uint256 => mapping(address => Listing))) public listings;
    address public oracle; address public paymentToken; uint256 public fee; uint256 public BASIS_POINTS; address public feeReceipient;

    function buyItem(address _nftAddress,uint256 _tokenId,address _owner,uint256 _quantity) external {
        require(msg.sender != _owner, "Cannot buy your own item");
        Listing memory listedItem = listings[_nftAddress][_tokenId][_owner];
        require(listedItem.quantity >= _quantity, "not enough quantity");
        if (IERC165(_nftAddress).supportsInterface(0x80ac58cd)) { IERC721(_nftAddress).safeTransferFrom(_owner, msg.sender, _tokenId); }
        else { /* omitted 1155 */ }
        if (listedItem.quantity == _quantity) { delete listings[_nftAddress][_tokenId][_owner]; } else { listings[_nftAddress][_tokenId][_owner].quantity -= _quantity; }
        TreasureNFTOracle(oracle).reportSale(_nftAddress, _tokenId, paymentToken, listedItem.pricePerItem);
        _buyItem(listedItem.pricePerItem, _quantity, _owner);
    }

    function _buyItem(uint256 _pricePerItem, uint256 _quantity, address _owner) internal {
        uint256 totalPrice = _pricePerItem * _quantity;
        uint256 feeAmount = totalPrice * fee / BASIS_POINTS;
        IERC20(paymentToken).safeTransferFrom(msg.sender, feeReceipient, feeAmount);
        IERC20(paymentToken).safeTransferFrom(msg.sender, _owner, totalPrice - feeAmount);
    }

    function getListing(address a,uint256 id,address o) external view returns (uint256,uint256) { Listing memory l = listings[a][id][o]; return (l.quantity,l.pricePerItem); }
}

