// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract QBridge {
    address public owner;
    uint8 public relayerThreshold;
    mapping(address => bool) public isRelayer;

    enum ProposalStatus {Inactive, Active, Passed, Executed}
    struct Proposal { ProposalStatus status; uint8 yesVotesTotal; }
    mapping(bytes32 => Proposal) public proposals;

    event RelayerThresholdChanged(uint256 newThreshold);

    constructor(uint8 _threshold) {
        owner = msg.sender;
        relayerThreshold = _threshold;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "only owner");
        _;
    }

    modifier onlyRelayers() {
        require(isRelayer[msg.sender], "only relayer");
        _;
    }

    // Vulnerable: no validation on newThreshold (can be set to 0)
    function setRelayerThreshold(uint8 newThreshold) external onlyOwner {
        relayerThreshold = newThreshold;
        emit RelayerThresholdChanged(newThreshold);
    }

    function addRelayer(address r) external onlyOwner {
        isRelayer[r] = true;
    }

    // minimal vote logic to demonstrate consequence of threshold = 0
    function voteProposal(bytes32 id) external onlyRelayers {
        Proposal storage p = proposals[id];
        if (p.status == ProposalStatus.Inactive) p.status = ProposalStatus.Active;
        p.yesVotesTotal++;
        if (p.yesVotesTotal >= relayerThreshold) {
            p.status = ProposalStatus.Passed;
            _executeProposal(id);
        }
    }

    function _executeProposal(bytes32 id) internal {
        Proposal storage p = proposals[id];
        require(p.status == ProposalStatus.Passed, "not passed");
        p.status = ProposalStatus.Executed;
    }

    function getProposalStatus(bytes32 id) external view returns (uint8) {
        return uint8(proposals[id].status);
    }
}

contract QBridgeTest is Test {
    QBridge target;
    address ownerAddr;
    address relayer1;

    function setUp() public {
        ownerAddr = makeAddr("owner");
        relayer1 = makeAddr("relayer1");
        // deploy as owner with initial threshold = 2
        vm.prank(ownerAddr);
        target = new QBridge(2);
        // owner adds a single relayer
        vm.prank(ownerAddr);
        target.addRelayer(relayer1);
    }

    // Demonstrates that owner can set threshold to 0 (no validation)
    // and a single relayer's single vote immediately executes a proposal.
    function test_owner_sets_threshold_to_zero_and_relayer_executes() public {
        bytes32 proposalId = keccak256("proposal-1");

        // owner lowers the threshold to 0 (vulnerable: no validation)
        vm.prank(ownerAddr);
        target.setRelayerThreshold(0);
        assertEq(target.relayerThreshold(), 0);

        // now the single relayer votes; because threshold == 0, the proposal is
        // considered Passed/Executed immediately even though consensus should
        // have required more votes.
        vm.prank(relayer1);
        target.voteProposal(proposalId);

        // check that proposal is Executed (enum value 3)
        assertEq(target.getProposalStatus(proposalId), uint8(3));
    }
}

