// Minimal AccessControl stub
contract AccessControl {
    mapping(bytes32 => mapping(address => bool)) private _roles;
    function _setupRole(bytes32 role, address account) internal { _roles[role][account] = true; }
    function hasRole(bytes32 role, address account) public view returns (bool) { return _roles[role][account]; }
    function revokeRole(bytes32 role, address account) public { _roles[role][account] = false; }
}

// Minimal vulnerable replica (only state/functions used by the PoC)
contract NFTFloorOracle is AccessControl {
    bytes32 public constant UPDATER_ROLE = keccak256("UPDATER_ROLE");

    address[] public feeders;
    struct FeederPosition { bool registered; uint8 index; }
    mapping(address => FeederPosition) public feederPositionMap;

    event FeederAdded(address indexed feeder);
    event FeederRemoved(address indexed feeder);

    constructor() { _addFeeder(msg.sender); }

    modifier onlyWhenFeederExisted(address _feeder) {
        require(_isFeederExisted(_feeder), "NFTOracle: feeder not existed");
        _;
    }

    function _isFeederExisted(address _feeder) internal view returns (bool) {
        return feederPositionMap[_feeder].registered;
    }

    function _addFeeder(address _feeder) internal {
        feeders.push(_feeder);
        feederPositionMap[_feeder].index = uint8(feeders.length - 1);
        feederPositionMap[_feeder].registered = true;
        _setupRole(UPDATER_ROLE, _feeder);
        emit FeederAdded(_feeder);
    }

    // Vulnerable: no access control — anyone can call this
    function removeFeeder(address _feeder) external onlyWhenFeederExisted(_feeder) {
        _removeFeeder(_feeder);
    }

    function _removeFeeder(address _feeder) internal {
        uint8 feederIndex = feederPositionMap[_feeder].index;
        if (feeders.length > 0 && feeders[feederIndex] == _feeder) {
            feeders[feederIndex] = feeders[feeders.length - 1];
            feeders.pop();
        }
        delete feederPositionMap[_feeder];
        revokeRole(UPDATER_ROLE, _feeder);
        emit FeederRemoved(_feeder);
    }
}

contract NFTFloorOracleTest is Test {
    NFTFloorOracle target;
    address attacker;

    function setUp() public {
