        target = new NFTFloorOracle();
        attacker = makeAddr("attacker");
    }

    function test_attacker_exploits_removeFeeder() public {
        // Initially, this test contract (address(this)) is a feeder with UPDATER_ROLE
        assertTrue(target.hasRole(target.UPDATER_ROLE(), address(this)));

