        require(claimAmt <= ggpRewards, "InvalidAmount");

        staking.decreaseGGPRewards(msg.sender, ggpRewards);

        Vault vault = Vault(getContractAddress("Vault"));
        uint256 restakeAmt = ggpRewards - claimAmt;
