    function hashOrder(Order memory order) public pure returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                order.maker,
                order.isCall,
                order.isLong,
                order.baseAsset,
                order.strike,
                order.premium,
                order.duration,
                order.expiration,
                order.nonce,
                abi.encodePacked(order.whitelist),
                abi.encodePacked(order.floorTokens)
            )
        );
    }

