        return _roles[role][account];
    }

    // intentionally public and unprotected in this stub (revoke will be called internally)
    function revokeRole(bytes32 role, address account) public {
        _roles[role][account] = false;
    }

    // initialize: set admin and initial feeders
    function initialize(address _admin, address[] memory _feeders) public {
        _setupRole(DEFAULT_ADMIN_ROLE, _admin);
        _setupRole(UPDATER_ROLE, _admin);
        for (uint256 i = 0; i < _feeders.length; i++) {
            _addFeeder(_feeders[i]);
        }
    }

