contract PaprController {
    using ReservoirOracleUnderwriter for ReservoirOracleUnderwriter.OracleInfo;

    address public pool;
    bool public token0IsUnderlying;
    PaprToken public papr;

    struct VaultInfo { uint200 debt; uint16 count; }
    mapping(address => mapping(ERC721 => VaultInfo)) public vault;

    constructor(PaprToken _papr) { papr = _papr; }

    function setPool(address _pool) external { pool = _pool; }
    function setVaultCount(address acct, ERC721 asset, uint16 c) external { vault[acct][asset].count = c; }

    function _maxDebt(uint256, uint256) internal pure returns (uint256) { return type(uint256).max; }
    function updateTarget() internal pure returns (uint256) { return 1; }
    function underwritePriceForCollateral(ERC721, ReservoirOracleUnderwriter.OracleInfo memory) internal pure returns (uint256) { return 1; }

    function _increaseDebt(address account, ERC721 asset, address mintTo, uint256 amount, ReservoirOracleUnderwriter.OracleInfo memory) internal {
        uint256 cachedTarget = updateTarget();
        uint256 newDebt = uint256(vault[account][asset].debt) + amount;
        uint256 oraclePrice = underwritePriceForCollateral(asset, oracleInfoPlaceholder());
        uint256 max = _maxDebt(uint256(vault[account][asset].count) * oraclePrice, cachedTarget);
        require(newDebt <= max);
        vault[account][asset].debt = uint200(newDebt);
        papr.mint(mintTo, amount);
    }

    // placeholder to satisfy types in this minimal replica
    function oracleInfoPlaceholder() internal pure returns (ReservoirOracleUnderwriter.OracleInfo memory) { return ReservoirOracleUnderwriter.OracleInfo({ dummy: 0 }); }

    function uniswapV3SwapCallback(int256 amount0Delta, int256 amount1Delta, bytes calldata _data) external {
        if (msg.sender != pool) revert("wrong caller");

        uint256 amountToPay;
        if (amount0Delta > 0) {
            amountToPay = uint256(amount0Delta);
            // simplified: underlying branch omitted for brevity
        } else {
            require(amount1Delta > 0);
            amountToPay = uint256(amount1Delta);
            (address account, ERC721 asset, ReservoirOracleUnderwriter.OracleInfo memory oracleInfo) = abi.decode(_data, (address, ERC721, ReservoirOracleUnderwriter.OracleInfo));
            _increaseDebt(account, asset, msg.sender, amountToPay, oracleInfo);
        }
    }
}

